const surveysList = `-- name: SurveysList :many
SELECT s.id, s.number, s.slug, s.name, s.description, s.status, s.questions, s.settings, s.closes_at, s.published_at, s.closed_at,
       s.created_at, s.updated_at, coalesce(u.name, '')::text AS created_by_name, s.created_by,
       (SELECT count(*) FROM survey_responses r WHERE r.survey_id = s.id AND r.kind <> 'test')::bigint AS started,
       (SELECT count(*) FROM survey_responses r WHERE r.survey_id = s.id AND r.kind <> 'test' AND r.completed_at IS NOT NULL)::bigint AS completed
FROM surveys s
LEFT JOIN users u ON u.id = s.created_by
WHERE s.workspace_id = $1 AND s.deleted_at IS NULL
ORDER BY s.created_at DESC
`

type SurveysListRow struct {
	ID            uuid.UUID       `json:"id"`
	Number        int64           `json:"number"`
	Slug          string          `json:"slug"`
	Name          string          `json:"name"`
	Description   string          `json:"description"`
	Status        string          `json:"status"`
	Questions     json.RawMessage `json:"questions"`
	Settings      json.RawMessage `json:"settings"`
	ClosesAt      *time.Time      `json:"closesAt"`
	PublishedAt   *time.Time      `json:"publishedAt"`
	ClosedAt      *time.Time      `json:"closedAt"`
	CreatedAt     time.Time       `json:"createdAt"`
	UpdatedAt     time.Time       `json:"updatedAt"`
	CreatedByName string          `json:"createdByName"`
	CreatedBy     *uuid.UUID      `json:"createdBy"`
	Started       int64           `json:"started"`
	Completed     int64           `json:"completed"`
}

func (q *Queries) SurveysList(ctx context.Context, workspaceID uuid.UUID) ([]SurveysListRow, error) {
	rows, err := q.db.Query(ctx, surveysList, workspaceID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SurveysListRow{}
	for rows.Next() {
		var i SurveysListRow
		if err := rows.Scan(
			&i.ID,
			&i.Number,
			&i.Slug,
			&i.Name,
			&i.Description,
			&i.Status,
			&i.Questions,
			&i.Settings,
			&i.ClosesAt,
			&i.PublishedAt,
			&i.ClosedAt,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.CreatedByName,
			&i.CreatedBy,
			&i.Started,
			&i.Completed,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
